const item = $input.item.json;
const errors = [];

const d = item.teamDiagnosis;
if (!d || !d.mainProblem) errors.push('teamDiagnosis.mainProblem fehlt in der finalen Pruefung.');

const p = item.playerProfile;
if (!p || !p.position || !p.role) errors.push('playerProfile.position/role fehlt in der finalen Pruefung.');

const s = item.playerSearch;
const shortlistNames = (s && Array.isArray(s.shortlist)) ? s.shortlist.map((c) => c.name) : [];
if (!s || shortlistNames.length === 0) errors.push('playerSearch.shortlist fehlt in der finalen Pruefung.');

const research = item.research;
if (!Array.isArray(research) || research.length === 0) errors.push('research fehlt in der finalen Pruefung.');

const r = item.recommendation;
if (!r || !r.candidate) {
  errors.push('recommendation.candidate fehlt in der finalen Pruefung.');
} else if (!shortlistNames.includes(r.candidate)) {
  errors.push('recommendation.candidate stammt nicht aus der validierten Shortlist.');
}
if (!r || !Array.isArray(r.alternatives)) errors.push('recommendation.alternatives fehlt in der finalen Pruefung.');
if (!r || !r.reasoning) errors.push('recommendation.reasoning fehlt in der finalen Pruefung.');
if (!r || !Array.isArray(r.risks) || r.risks.length === 0) errors.push('recommendation.risks fehlt oder ist leer in der finalen Pruefung.');
if (!r || !Array.isArray(r.uncertainties) || r.uncertainties.length === 0) errors.push('recommendation.uncertainties fehlt oder ist leer in der finalen Pruefung.');
if (!r || !r.nextStep) errors.push('recommendation.nextStep fehlt in der finalen Pruefung.');

const valid = errors.length === 0;

return [{
  json: {
    ...item,
    valid,
    errorMessage: valid
      ? undefined
      : 'Die finale Validierung ist fehlgeschlagen, es wird keine fachliche Empfehlung angezeigt.\n\n' + errors.join('\n')
  }
}];

const item = $json;
const d = item.teamDiagnosis || {};
const p = item.playerProfile || {};
const s = item.playerSearch || {};
const research = item.research || [];
const r = item.recommendation || {};

function escapeHtml(str) {
  return String(str ?? '')
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function sectionHeader(title) {
  return `<h3>${escapeHtml(title)}</h3>`;
}

// "Label: value" -> bold label, plain value
function labeledLine(label, value) {
  return `<p><strong>${escapeHtml(label)}:</strong> ${escapeHtml(value)}</p>`;
}

// --- Teamdiagnose ---
const teamdiagnoseBlock = `
  ${sectionHeader('Teamdiagnose')}
  ${labeledLine('Hauptproblem', d.mainProblem)}
  ${(d.hypotheses || []).map((h, i) => `<p><strong>Hypothese ${i + 1}:</strong> ${escapeHtml(h)}</p>`).join('')}
`;

// --- Spielerprofil ---
const spielerprofilBlock = `
  ${sectionHeader('Spielerprofil')}
  ${labeledLine('Position', p.position)}
  ${labeledLine('Rolle', p.role)}
  ${labeledLine('Begruendung', p.reasoning)}
`;

// --- Spielersuche ---
const spielersucheBlock = `
  ${sectionHeader('Spielersuche')}
  ${labeledLine('Longlist-Groesse', s.longlistSize)}
  ${(s.shortlist || []).map((c) => `<p>${escapeHtml(c.name)} (Score ${escapeHtml(c.score)})</p>`).join('')}
`;

// --- Recherche ---
const researchLines = [];
for (const x of research) {
  if (x.uncertain) {
    researchLines.push(`<p><strong>${escapeHtml(x.candidate)}:</strong> Recherche fehlgeschlagen / unsicher (${escapeHtml(x.uncertaintyReason || 'kein Grund angegeben')}).</p>`);
    continue;
  }
  researchLines.push(`<p><strong>${escapeHtml(x.candidate)}:</strong> ${escapeHtml(x.club)}, ${escapeHtml(x.contract)}, ${escapeHtml(x.marketValue)}, ${escapeHtml(x.injuries)} (Aggregat-Konfidenz ${escapeHtml(x.confidence)})</p>`);
  if (x.currentSituation) researchLines.push(`<p>Aktuelle Situation: ${escapeHtml(x.currentSituation)}</p>`);
  if (x.transferLikelihoodNotes) researchLines.push(`<p>Wechselwahrscheinlichkeit: ${escapeHtml(x.transferLikelihoodNotes)}</p>`);
  for (const evidence of (Array.isArray(x.evidence) ? x.evidence : [])) {
    researchLines.push(`<p>Evidence [${escapeHtml(evidence.fact)}]: ${escapeHtml(evidence.claim)} (Quelle: ${escapeHtml(evidence.source)}; URL: ${escapeHtml(evidence.url)}; Zeitpunkt: ${escapeHtml(evidence.timestamp)}; Konfidenz: ${escapeHtml(evidence.confidence)})</p>`);
  }
}
const rechercheBlock = `
  ${sectionHeader('Recherche')}
  ${researchLines.join('')}
`;

// --- Empfehlung ---
const empfehlungLines = [
  labeledLine('Bevorzugter Kandidat', r.candidate),
  labeledLine('Begruendung', r.reasoning),
  labeledLine('Naechster Schritt', r.nextStep)
];
if (r.candidateProfile) {
  const cp = r.candidateProfile;
  empfehlungLines.push(`<p>CSV-Analytics-Profil (Data Table football_scouting_raw): ${escapeHtml(cp.club)}, ${escapeHtml(cp.position)}, Alter ${escapeHtml(cp.age)}, Rating ${escapeHtml(cp.rating)}, ${escapeHtml(cp.goals)} Tore, ${escapeHtml(cp.assists)} Vorlagen in ${escapeHtml(cp.appearances)} Einsaetzen.</p>`);
}
const empfehlungBlock = `
  ${sectionHeader('Empfehlung')}
  ${empfehlungLines.join('')}
`;

const resultHtml = `
<p><strong>Verein:</strong> ${escapeHtml(item.teamPerformance?.club)}</p>
<p><strong>Auftrag:</strong> ${escapeHtml(item.objective)}</p>
${item.additionalContext ? labeledLine('Zusaetzlicher Kontext', item.additionalContext) : ''}
<p>⚠ Hinweis: Teamdiagnose und Spielerprofil (Bedarfsermittlung) werden von einem lokalen LLM auf Basis des CSV-Analytics-Adapters interpretiert. Recherche nutzt echte Websuche (Tavily) und weist Quelle, URL, Zeitpunkt und Konfidenz claim-spezifisch aus; der CSV-Analytics-Adapter bleibt ein temporaerer Ersatz fuer Qlik MCP.</p>
${teamdiagnoseBlock}
${spielerprofilBlock}
${spielersucheBlock}
${rechercheBlock}
${empfehlungBlock}
`;

return {
  json: {
    ...item,
    formattedResult: resultHtml.replace(/<[^>]+>/g, '').trim(), // keep a plain-text version if you still use formattedResult elsewhere
    resultHtml
  }
};

const item = $input.item.json;
if (item.valid === false) {
  throw new Error('[RESULT_PRESENTATION] ' + (item.errorMessage || 'Ergebnis aufbereiten ist fehlgeschlagen.'));
}
return [{ json: { ...item, status: 'success' } }];
